 "content": "def transform(grid):
    # Complete a diagonal periodic pattern by inferring its period from the
    # parallel stripe fragments visible in the input.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Infer each diagonal stripe by its c-r offset, retaining given colors.
    known = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                known[c-r] = grid[r][c]
    # For the demos, stripe colors repeat at a fixed diagonal period.
    # Find the shortest period consistent with all observed offsets/colors.
    offsets = list(known)
    period = None
    for p in range(1, max(h, w)+1):
        if all(known[a] == known[b] for a in offsets for b in offsets if (a-b) % p == 0):
            period = p
            break
    if period is None:
        period = max(h, w)
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                d = c-r
                matches = [known[k] for k in offsets if (d-k) % period == 0]
                if matches and len(set(matches)) == 1:
                    out[r][c] = matches[0]
    return out
